compose_config:
{
  "name": "news-benchmark",
  "networks": {
    "default": {
      "name": "news-benchmark_default",
      "ipam": {}
    }
  },
  "services": {
    "kafka": {
      "cpus": 2,
      "command": null,
      "entrypoint": null,
      "environment": {
        "KAFKA_ADVERTISED_LISTENERS": "PLAINTEXT://kafka:9092,EXTERNAL://localhost:19092",
        "KAFKA_CONTROLLER_LISTENER_NAMES": "CONTROLLER",
        "KAFKA_CONTROLLER_QUORUM_VOTERS": "1@kafka:9093",
        "KAFKA_GROUP_INITIAL_REBALANCE_DELAY_MS": "0",
        "KAFKA_INTER_BROKER_LISTENER_NAME": "PLAINTEXT",
        "KAFKA_LISTENERS": "PLAINTEXT://:9092,CONTROLLER://:9093,EXTERNAL://:19092",
        "KAFKA_LISTENER_SECURITY_PROTOCOL_MAP": "CONTROLLER:PLAINTEXT,PLAINTEXT:PLAINTEXT,EXTERNAL:PLAINTEXT",
        "KAFKA_NODE_ID": "1",
        "KAFKA_NUM_PARTITIONS": "1",
        "KAFKA_OFFSETS_TOPIC_REPLICATION_FACTOR": "1",
        "KAFKA_PROCESS_ROLES": "broker,controller",
        "KAFKA_TRANSACTION_STATE_LOG_MIN_ISR": "1",
        "KAFKA_TRANSACTION_STATE_LOG_REPLICATION_FACTOR": "1"
      },
      "image": "apache/kafka:3.9.1",
      "mem_limit": "1572864000",
      "networks": {
        "default": null
      },
      "healthcheck": {
        "test": [
          "CMD-SHELL",
          "/opt/kafka/bin/kafka-topics.sh --bootstrap-server localhost:9092 --list \u003e/dev/null"
        ],
        "timeout": "10s",
        "interval": "10s",
        "retries": 15
      },
      "ports": [
        {
          "mode": "ingress",
          "host_ip": "127.0.0.1",
          "target": 19092,
          "published": "19092",
          "protocol": "tcp"
        }
      ]
    },
    "postgres": {
      "cpus": 2,
      "command": null,
      "entrypoint": null,
      "environment": {
        "POSTGRES_DB": "benchmark",
        "POSTGRES_PASSWORD": "benchmark_local_only",
        "POSTGRES_USER": "benchmark"
      },
      "image": "postgres:16.6-bookworm",
      "mem_limit": "1073741824",
      "networks": {
        "default": null
      },
      "volumes": [
        {
          "type": "volume",
          "source": "benchmark-postgres",
          "target": "/var/lib/postgresql/data",
          "volume": {}
        }
      ],
      "healthcheck": {
        "test": [
          "CMD-SHELL",
          "pg_isready -U benchmark"
        ],
        "timeout": "5s",
        "interval": "5s",
        "retries": 15
      },
      "ports": [
        {
          "mode": "ingress",
          "host_ip": "127.0.0.1",
          "target": 5432,
          "published": "15432",
          "protocol": "tcp"
        }
      ]
    },
    "redis": {
      "cpus": 2,
      "command": [
        "redis-server",
        "--appendonly",
        "yes",
        "--appendfsync",
        "everysec"
      ],
      "entrypoint": null,
      "image": "redis:7.4-alpine",
      "mem_limit": "1572864000",
      "networks": {
        "default": null
      },
      "volumes": [
        {
          "type": "volume",
          "source": "benchmark-redis",
          "target": "/data",
          "volume": {}
        }
      ],
      "healthcheck": {
        "test": [
          "CMD",
          "redis-cli",
          "ping"
        ],
        "timeout": "3s",
        "interval": "5s",
        "retries": 10
      }
    },
    "worker": {
      "cpus": 2,
      "command": [
        "sleep",
        "infinity"
      ],
      "entrypoint": null,
      "environment": {
        "JAVA_TOOL_OPTIONS": "-XX:ActiveProcessorCount=2",
        "PYTHONUNBUFFERED": "1",
        "PYTHONUTF8": "1",
        "SPARK_LOCAL_IP": "127.0.0.1"
      },
      "mem_limit": "5368709120",
      "networks": {
        "default": null
      },
      "volumes": [
        {
          "type": "bind",
          "source": "C:\\Users\\GIGABYTE\\OneDrive\\Documents\\document\\2026.1\\bigdata\\News-Big-Data-Platform\\benchmark",
          "target": "/bench",
          "bind": {}
        },
        {
          "type": "volume",
          "source": "benchmark-storage",
          "target": "/storage",
          "volume": {}
        },
        {
          "type": "bind",
          "source": "C:\\Users\\GIGABYTE\\OneDrive\\Documents\\document\\2026.1\\bigdata\\News-Big-Data-Platform\\src",
          "target": "/project/src",
          "read_only": true,
          "bind": {}
        }
      ],
      "working_dir": "/bench",
      "build": {
        "context": "C:\\Users\\GIGABYTE\\OneDrive\\Documents\\document\\2026.1\\bigdata\\News-Big-Data-Platform\\benchmark",
        "dockerfile": "Dockerfile"
      },
      "depends_on": {
        "kafka": {
          "condition": "service_healthy",
          "required": true
        },
        "postgres": {
          "condition": "service_healthy",
          "required": true
        },
        "redis": {
          "condition": "service_healthy",
          "required": true
        }
      }
    }
  },
  "volumes": {
    "benchmark-postgres": {
      "name": "news-benchmark_benchmark-postgres"
    },
    "benchmark-redis": {
      "name": "news-benchmark_benchmark-redis"
    },
    "benchmark-storage": {
      "name": "news-benchmark_benchmark-storage"
    }
  }
}
